<?php require __DIR__.'/_nav.php';use OCP\IURLGenerator;$url=\OC::$server->get(IURLGenerator::class);script('reinhardterp','inventory');$materials=$_['materials'];$total=count($materials);$low=count(array_filter($materials,fn($m)=>(float)($m['stock_quantity']??0)<=(float)($m['min_stock']??0)));$out=count(array_filter($materials,fn($m)=>(float)($m['stock_quantity']??0)<=0));$value=array_sum(array_map(fn($m)=>(float)($m['stock_quantity']??0)*(float)($m['purchase_price']??0),$materials));?>
<div id="app-content"><div class="erp-page erp-inventory-page"><div class="erp-page-head"><div><h1>Lagerübersicht</h1><p class="erp-sub">Bestände prüfen, Material suchen und Lagerbewegungen buchen.</p></div><a class="button" href="<?php p($url->linkToRoute('reinhardterp.module.materials'));?>">Materialstamm</a></div>
<div class="erp-material-summary"><button class="erp-stat inventory-filter" data-filter=""><span>Artikel</span><strong><?php p($total);?></strong></button><button class="erp-stat inventory-filter" data-filter="low"><span>Mindestbestand</span><strong><?php p($low);?></strong></button><button class="erp-stat inventory-filter" data-filter="out"><span>Nicht auf Lager</span><strong><?php p($out);?></strong></button><div class="erp-stat"><span>Lagerwert EK</span><strong><?php p(number_format($value,2,',','.').' €');?></strong></div></div>
<div class="erp-toolbar"><input id="inventory-search" type="search" placeholder="Bestand suchen …"><span id="inventory-result-count"><?php p($total);?> Treffer</span></div>
<div class="erp-table"><table><thead><tr><th>Artikel</th><th>Bezeichnung</th><th>Gruppe</th><th>Lagerort</th><th>Bestand</th><th>Minimum</th><th>Bestellmenge</th><th>Lieferant</th><th>Status</th></tr></thead><tbody id="inventory-table-body"><?php foreach($materials as $m):$stock=(float)($m['stock_quantity']??0);$min=(float)($m['min_stock']??0);$state=$stock<=0?'out':($stock<=$min?'low':'ok');$search=mb_strtolower(implode(' ',[$m['article_no']??'',$m['name']??'',$m['group_name']??$m['material_group']??'',$m['supplier_name']??$m['supplier']??'',$m['storage_location']??'']));?><tr data-search="<?php p($search);?>" data-stock="<?php p($state);?>"><td><strong><?php p($m['article_no']??'');?></strong></td><td><?php p($m['name']);?></td><td><?php p($m['group_name']??$m['material_group']??'—');?></td><td><?php p($m['storage_location']??'—');?></td><td><?php p(number_format($stock,3,',','.').' '.($m['unit']??''));?></td><td><?php p(number_format($min,3,',','.'));?></td><td><?php p(number_format((float)($m['reorder_quantity']??0),3,',','.'));?></td><td><?php p($m['supplier_name']??$m['supplier']??'—');?></td><td><span class="erp-stock-badge erp-stock-<?php p($state);?>"><?php p($state==='out'?'Leer':($state==='low'?'Nachbestellen':'OK'));?></span></td></tr><?php endforeach;?></tbody></table><div id="inventory-empty" class="erp-empty" hidden>Kein Material für diesen Filter gefunden.</div></div>
<details class="erp-form-card" open><summary><strong>Lagerbewegung buchen</strong></summary><form method="post" action="<?php p($url->linkToRoute('reinhardterp.business.saveStockMovement'));?>"><input type="hidden" name="requesttoken" value="<?php p($_['requesttoken']);?>"><div class="erp-form-grid"><div class="erp-span-2"><label>Material suchen</label><input id="movement-material-search" type="search" placeholder="Artikelnummer oder Bezeichnung"><label>Material</label><select id="movement-material-select" name="materialId" required><?php foreach($materials as $m):?><option value="<?php p($m['id']);?>" data-search="<?php p(mb_strtolower(($m['article_no']??'').' '.$m['name'].' '.($m['barcode']??'')));?>"><?php p(($m['article_no']??'').' · '.$m['name'].' · '.number_format((float)($m['stock_quantity']??0),3,',','.').' '.($m['unit']??''));?></option><?php endforeach;?></select></div><div><label>Bewegung</label><select name="movementType"><option value="in">Zugang</option><option value="out">Entnahme</option><option value="adjustment">Bestandskorrektur</option></select></div><div><label>Menge / neuer Bestand</label><input type="number" step="0.001" name="quantity" required></div><div><label>Projekt</label><select name="projectId"><option value="">ohne Projekt</option><?php foreach($_['projects'] as $p):?><option value="<?php p($p['id']);?>"><?php p($p['project_no'].' · '.$p['title']);?></option><?php endforeach;?></select></div><div><label>Notiz</label><input name="note"></div></div><button class="button primary">Lagerbewegung buchen</button></form></details>
<details class="erp-form-card"><summary><strong>Letzte Lagerbewegungen</strong></summary><div class="erp-table"><table><thead><tr><th>Zeitpunkt</th><th>Material</th><th>Bewegung</th><th>Menge</th><th>Projekt</th><th>Notiz</th></tr></thead><tbody><?php foreach($_['movements'] as $m):$labels=['in'=>'Zugang','out'=>'Entnahme','adjustment'=>'Korrektur'];?><tr><td><?php p(date('d.m.Y H:i',strtotime($m['created_at'])));?></td><td><?php p(($m['article_no']??'').' · '.$m['material_name']);?></td><td><?php p($labels[$m['movement_type']]??$m['movement_type']);?></td><td><?php p(number_format((float)$m['quantity'],3,',','.').' '.$m['unit']);?></td><td><?php p($m['project_no']?:'—');?></td><td><?php p($m['note']);?></td></tr><?php endforeach;?></tbody></table></div></details>
</div></div>
